package net.dawson.adorablehamsterpets.client.particle;

import java.awt.Color;
import java.util.Locale;
import me.fzzyhmstrs.fzzy_config.util.EnumTranslatable;
import net.minecraft.util.RandomSource;
import org.jetbrains.annotations.NotNull;

public enum PixieDustParticleTheme implements EnumTranslatable
{
    GOLD(0),
    CRIMSON(-42),
    LAVENDER(-115),
    ICE(145),
    EMERALD(100);

    private final int[] colors = new int[7];

    private PixieDustParticleTheme(int themeHueOffset) {
        float hOffset = themeHueOffset;
        this.colors[0] = PixieDustParticleTheme.toRgb(47.0f + hOffset, 15.0f, 100.0f);
        this.colors[1] = PixieDustParticleTheme.toRgb(50.0f + hOffset, 56.0f, 99.0f);
        this.colors[2] = PixieDustParticleTheme.toRgb(49.0f + hOffset, 50.0f, 90.0f);
        this.colors[3] = PixieDustParticleTheme.toRgb(41.0f + hOffset, 99.0f, 81.0f);
        this.colors[4] = PixieDustParticleTheme.toRgb(45.0f + hOffset, 75.0f, 75.0f);
        this.colors[5] = PixieDustParticleTheme.toRgb(42.0f + hOffset, 72.0f, 39.0f);
        this.colors[6] = PixieDustParticleTheme.toRgb(44.0f + hOffset, 68.0f, 29.0f);
    }

    private static int toRgb(float h, float s, float b) {
        if ((h %= 360.0f) < 0.0f) {
            h += 360.0f;
        }
        s = Math.max(0.0f, Math.min(100.0f, s));
        b = Math.max(0.0f, Math.min(100.0f, b));
        return Color.HSBtoRGB(h / 360.0f, s / 100.0f, b / 100.0f) & 0xFFFFFF;
    }

    public int getRandomColor(RandomSource random) {
        return this.colors[random.m_188503_(this.colors.length)];
    }

    @NotNull
    public String prefix() {
        return "config.adorablehamsterpets.enum.pixie_dust_color_theme";
    }

    @NotNull
    public String translationKey() {
        return this.prefix() + "." + this.name().toLowerCase(Locale.ROOT);
    }
}

