        if (!this.initialized) {
            this.initialize();
            this.initialized = true;
        }
        HttpRequest request = HttpRequest.newBuilder().uri(URI.create(REMOTE_URL)).GET().build();
        ((CompletableFuture)this.httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString()).thenAccept(response -> {
            if (response.statusCode() == 200) {
                Type type = new TypeToken<Map<String, Set<String>>>(){}.getType();
                Map newPerks = (Map)GSON.fromJson((String)response.body(), type);
                if (newPerks != null) {
                    this.perks = newPerks;
                    this.saveCache();
                    AdorableHamsterPets.LOGGER.info("[Perks] Successfully refreshed player perks.");
                }
            } else {
                AdorableHamsterPets.LOGGER.warn("[Perks] Failed to fetch perks from remote (Status {}).", (Object)response.statusCode());
            }
        })).exceptionally(e -> {
            AdorableHamsterPets.LOGGER.warn("[Perks] Exception while fetching perks from remote: {}. Using cached data if available.", (Object)e.toString());
            return null;
        });
    }

    public boolean hasPerk(String username, String perkId) {
        if (Platform.isDevelopmentEnvironment()) {
            return true;
        }
        Set<String> users = this.perks.get(perkId);
        if (users == null) {
            return false;
        }
        return users.contains(username);
    }

    private void initialize() {
        this.httpClient = HttpClient.newHttpClient();
        Path configDir = Platform.getConfigFolder().resolve("adorablehamsterpets");
        this.cacheFilePath = configDir.resolve("perks.cache.json");
        try {
            Files.createDirectories(configDir, new FileAttribute[0]);
        }
        catch (IOException e) {
            AdorableHamsterPets.LOGGER.error("[Perks] Failed to create config directory.", (Throwable)e);
        }
        this.loadCache();
    }

    private void loadCache() {
        if (Files.exists(this.cacheFilePath, new LinkOption[0])) {
            try (FileReader reader = new FileReader(this.cacheFilePath.toFile());){
                Type type = new TypeToken<Map<String, Set<String>>>(){}.getType();
                Map cached = (Map)GSON.fromJson((Reader)reader, type);
                if (cached != null) {
                    this.perks = cached;
                }
            }
            catch (Exception e) {
                AdorableHamsterPets.LOGGER.error("[Perks] Failed to load cached perks or file was corrupted.", (Throwable)e);

